class Solution:
    def nthSmallest(self, n, k):
        C = [[0] * 51 for _ in range(51)]
        for i in range(51):
            C[i][0] = 1
            for j in range(1, i + 1):
                C[i][j] = C[i-1][j-1] + C[i-1][j]
        acc, hi = 0, -1
        for p in range(k - 1, 50):
            c = C[p][k - 1]
            if n <= acc + c:
                hi = p
                break
            acc += c
        res = 1 << hi
        r, rem = n - acc, k - 1
        for b in range(hi - 1, -1, -1):
            if rem == 0:
                break
            c = C[b][rem] if b >= rem else 0
            if r > c:
                r -= c
                res |= 1 << b
                rem -= 1
        return res

