class Solution {
public:
    long long C[51][51];
    int nthSmallest(int n, int k) {
        for (int i = 0; i < 51; i++) {
            C[i][0] = 1;
            for (int j = 1; j <= i; j++) C[i][j] = C[i-1][j-1] + C[i-1][j];
        }
        long long acc = 0; int hi = -1;
        for (int p = k - 1; p < 50; p++) {
            long long c = C[p][k-1];
            if ((long long)n <= acc + c) { hi = p; break; }
            acc += c;
        }
        long long res = 1LL << hi, r = n - acc;
        int rem = k - 1;
        for (int b = hi - 1; b >= 0 && rem > 0; b--) {
            long long c = (b >= rem) ? C[b][rem] : 0;
            if (r > c) { r -= c; res |= 1LL << b; rem--; }
        }
        return (int)res;
    }
};

