var nthSmallest = function(n, k) {
    const C = Array.from({length: 51}, () => new Array(51).fill(0));
    for (let i = 0; i < 51; i++) {
        C[i][0] = 1;
        for (let j = 1; j <= i; j++) C[i][j] = C[i-1][j-1] + C[i-1][j];
    }
    let acc = 0, hi = -1;
    for (let p = k - 1; p < 50; p++) {
        const c = C[p][k-1];
        if (n <= acc + c) { hi = p; break; }
        acc += c;
    }
    let res = 2 ** hi, r = n - acc, rem = k - 1;
    for (let b = hi - 1; b >= 0 && rem > 0; b--) {
        const c = b >= rem ? C[b][rem] : 0;
        if (r > c) { r -= c; res += 2 ** b; rem--; }
    }
    return res;
};
